    """Return (first_day, last_day) ISO dates for a "YYYY-MM" period."""
    year, month = (int(part) for part in period.split("-"))
    last = calendar.monthrange(year, month)[1]
    return ("%04d-%02d-01" % (year, month), "%04d-%02d-%02d" % (year, month, last))


